}
```

For example, if `length` is 12, the output could be something like "A7b#9zPq!2F".

### Solution:
```rust
use rand::RngCore;

/// Returns cryptographically secure PRNG
/// Uses ThreadRng - <https://rust-random.github.io/rand/rand/rngs/struct.ThreadRng.html>
/// which is StgRng (ChaCha block cipher with 12 as of July 2021 -
/// <https://rust-random.github.io/rand/rand/rngs/struct.StdRng.html>) seeded from OsRng -
/// <https://rust-random.github.io/rand/rand/rngs/struct.OsRng.html> which is a random number
/// generator that retrieves randomness from the operating system.
pub fn secure_rng() -> impl RngCore {
    use rand::thread_rng;
    thread_rng()
}

pub fn generate_password(length: usize) -> String {
    const CHARSET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*()-_=+[]{}|;:,.<>?";
    let charset_length = CHARSET.len() as u32;

    let mut password = String::with_capacity(length);
    let mut rng = secure_rng();

    for _ in 0..length {
        let idx = rng.next_u32() % charset_length;
        password.push(CHARSET[idx as usize] as char);
    }

    password
}
```

In the solution, the `generate_password` function uses the `secure_rng` function to obtain random bytes and then converts those bytes into a password string by selecting characters from the specified character set. The function ensures that the password is generated in a secure and cryptographically strong manner.

