struct TextEditor {
    text: String,
    history: Vec<String>,
}

impl TextEditor {
    fn new() -> Self {
        TextEditor {
            text: String::new(),
            history: Vec::new(),
        }
    }

    fn handle_event(&mut self, event: &str) {
        // Handle user input event and update the text
        // Add the event to the history
        self.text.push_str(event);
        self.history.push(event.to_string());
    }

    fn undo(&mut self) {
        // Implement the undo functionality to revert the most recent change
        // Update the text and history accordingly
        if let Some(last_event) = self.history.pop() {
            let len = last_event.len();
            self.text.truncate(self.text.len() - len);
        }
    }
}
