```

Your task is to write a Rust function `parse_config` that takes the configuration file as input and returns a struct representing the parsed data. The struct should have fields for DNS servers and network interface settings.

The `DnsConfig` struct should have the following fields:
- `primary_dns: String` (to store the primary DNS server)
- `secondary_dns: Option<String>` (to store the secondary DNS server, which may be absent)

The `InterfaceConfig` enum should have the following variants:
- `Static { name: String, metric: u32, ip: String, netmask: String, gateway: String }` (for static network configuration)
- `Dhcp { name: String, metric: u32, options: Vec<DhcpOption> }` (for DHCP network configuration)

The `DhcpOption` enum should have the following variants:
- `WWW` (representing the World Wide Web option)
- `VoIP` (representing the Voice over IP option)

Your task is to implement the `parse_config` function to parse the given configuration file and return a struct containing the parsed DNS and interface settings.

```rust
enum Ether {
    Static,
    Dhcp,
}

enum DhcpOption {
    WWW,
    VoIP,
}

struct DnsConfig {
    primary_dns: String,
    secondary_dns: Option<String>,
}

enum InterfaceConfig {
    Static {
        name: String,
        metric: u32,
        ip: String,
        netmask: String,
        gateway: String,
    },
    Dhcp {
        name: String,
        metric: u32,
        options: Vec<DhcpOption>,
    },
}

fn parse_config(config: &str) -> Result<(DnsConfig, InterfaceConfig), String> {
    // Your implementation here
}
```

### Solution:
```rust
use regex::Regex;

fn parse_config(config: &str) -> Result<(DnsConfig, InterfaceConfig), String> {
    let dns_regex = Regex::new(r#"dns\s*{\s*primary:\s*"([^"]+)"\s*,\s*secondary:\s*(Some\("([^"]+)"\)|None)\s*}"#).unwrap();
    let interface_regex = Regex::new(r#"interface\s*{\s*type:\s*(Ether::Static|Ether::Dhcp),\s*name:\s*"([^"]+)"\s*,\s*metric:\s*(\d+),\s*options:\s*\[([^\]]*)\]\s*}"#).unwrap();

    let dns_caps = dns_regex.captures(config).ok_or("Invalid DNS configuration")?;
    let primary_dns = dns_caps.get(1).unwrap().as_str().to_string();
    let secondary_dns = match dns_caps.get(2).unwrap().as_str() {
        "None" => None,
        _ => Some(dns_caps.get(3).unwrap().as_str().to_string()),
    };
    let dns_config = DnsConfig {
        primary_dns,
        secondary_dns,
    };

    let interface_caps = interface_regex.captures(config).ok_or("Invalid interface configuration")?;
    let interface_type = match interface_caps.get(1).unwrap().as_str() {
        "Ether::Static" => Ether::Static,
        "Ether::Dhcp" => Ether::Dhcp,
        _ => return Err("Invalid interface type"),
    };
    let name = interface_caps.get(2).unwrap().as_str().to_string();
    let metric = interface_caps.get(3).unwrap().as_str().parse().map_err(|_| "Invalid metric")?;
    let options: Vec<DhcpOption> = interface_caps.get(4).unwrap().as_str().split(',').map(|opt| {
        match opt.trim() {
            "Dhcp::WWW" => Ok(DhcpOption::WWW),
            "Dhcp::VoIP" => Ok(DhcpOption::VoIP),
            _ => Err("Invalid DHCP option"),
        }
    }).collect::<Result<_, _>>()?;
    let interface_config = match interface_type {
        Ether::Static => InterfaceConfig::Static {
            name,
            metric,
            ip: String::new(), // Parse IP, netmask, gateway from the configuration
            netmask: String::new(),
            gateway: String::new(),
        },
        Ether::Dhcp => InterfaceConfig::Dhcp {
            name,
            metric,
            options,
        },
    };

    Ok((dns_config, interface_config))
