use url::Url;
use std::fs;

struct DatabaseConfig {
    url: String,
    user: Option<String>,
    password_file: Option<String>,
}

fn modify_database_url(database_config: &DatabaseConfig) -> Result<Url, String> {
    let mut url = Url::parse(database_config.url.as_str()).map_err(|e| format!("Invalid connection URL: {}", e))?;

    if let Some(user) = database_config.user.as_ref() {
        if url.username().is_empty() {
            url.set_username(user.as_str()).map_err(|e| format!("Could not append username to the connection URL: {}", e))?;
