  const outer = RegExp(/^.*0x[a-fA-F0-9]*.*/, 'gm');
  const inner = RegExp(/0x[a-fA-F0-9]*/, 'g');

  return input.replace(outer, (match) => {
    match = match.replace(/'/g, '');

    if (match.includes('domain')) {
      return match;
    }

    const hexStrings = match.match(inner);
    if (hexStrings) {
      hexStrings.forEach((hexStr) => {
        const base64Str = Buffer.from(hexStr.slice(2), 'hex').toString('base64');
        match = match.replace(hexStr, base64Str);
      });
    }

    return match;
  });
}
```

