### Solution:
```typescript
interface DeclarationInfo {
  name: string;
  isArray: boolean;
  hasOptionalChaining: boolean;
}

function processDeclarations(declarations: string[]): DeclarationInfo[] {
  const result: DeclarationInfo[] = [];

  for (const declaration of declarations) {
    const [name, type] = declaration
      .replace('declare ', '')
      .replace(';', '')
      .split(':')
      .map((str) => str.trim());

    const isArray = type.includes('[]');
