def numbering(source_text, numbering_style, output_format, options):
    if output_format == 'latex':
        prefix, start_number = numbering_style
        if isinstance(source_text, list):
            numbered_list = [f"{prefix} {start_number + i}. {item}" for i, item in enumerate(source_text)]
            return '\n'.join(numbered_list)
        else:
