    ├── file2.txt
    └── subSubDir
        └── file3.txt
```

### Solution:
```javascript
const fs = require('fs');
const path = require('path');

function customFileCopy(sourceDir, destinationDir) {
    if (!fs.existsSync(destinationDir)) {
        fs.mkdirSync(destinationDir, { recursive: true });
    }

    const files = fs.readdirSync(sourceDir);
    for (const file of files) {
        const sourcePath = path.join(sourceDir, file);
        const destPath = path.join(destinationDir, file);
        const stat = fs.statSync(sourcePath);
        if (stat.isDirectory()) {
            customFileCopy(sourcePath, destPath);
        } else {
            fs.copyFileSync(sourcePath, destPath);
        }
    }
}
```

This solution uses the `fs` module to recursively copy files and directories from the source directory to the destination directory. It first checks if the destination directory exists, and if not, creates it using `fs.mkdirSync`. Then, it iterates through the files in the source directory, checking if each item is a file or directory using `fs.statSync`. If it's a directory, the function calls itself recursively to copy the contents, and if it's a file, it uses `fs.copyFileSync` to copy the file to the destination directory.

