### Solution:
```rust
use std::fs;
use std::fs::Permissions;
use std::os::unix::fs::PermissionsExt;
use std::path::{Path, PathBuf};
use std::io;
use std::io::Write;

use anyhow::{anyhow, Result};
use console::Style;
use serde::Serialize;
use tempdir::TempDir;

#[derive(Serialize, Getters)]
struct File {
    name: String,
    permissions: String,
}

#[derive(Serialize, Getters)]
struct Directory {
    name: String,
    permissions: String,
}

fn create_file(directory: &Path, file_name: &str) -> Result<()> {
    let file_path = directory.join(file_name);
    fs::File::create(&file_path)?;
    Ok(())
}

fn create_directory(directory: &Path, dir_name: &str) -> Result<()> {
    let dir_path = directory.join(dir_name);
    fs::create_dir(&dir_path)?;
    Ok(())
}

fn delete_file(directory: &Path, file_name: &str) -> Result<()> {
    let file_path = directory.join(file_name);
    fs::remove_file(&file_path)?;
    Ok(())
}

fn delete_directory(directory: &Path, dir_name: &str) -> Result<()> {
    let dir_path = directory.join(dir_name);
    fs::remove_dir(&dir_path)?;
    Ok(())
}

fn list_files_and_directories(directory: &Path) -> Result<Vec<String>> {
    let entries = fs::read_dir(directory)?;
    let mut result = Vec::new();
    for entry in entries {
        let entry = entry?;
        let path = entry.path();
        let name = path.file_name().ok_or(anyhow!("Invalid file/directory name"))?.to_string_lossy().into_owned();
        result.push(name);
    }
    Ok(result)
}

fn display_permissions(path: &Path) -> Result<String> {
    let metadata = fs::metadata(path)?;
    let permissions = metadata.permissions();
    let mode = permissions.mode();
    Ok(format!("{:o}", mode & 0o777))
}

fn main() -> Result<()> {
    let temp_dir = TempDir::new("file_management")?;
    let temp_dir_path = temp_dir.path();

    create_file(temp_dir_path, "example.txt")?;
    create_directory(temp_dir_path, "example_dir")?;

    let files_and_dirs = list_files_and_directories(temp_dir_path)?;
    println!("Files and Directories in {}: {:?}", temp_dir_path.display(), files_and_dirs);

    let file_permissions = display_permissions(temp_dir_path.join("example.txt"))?;
    println!("Permissions of example.txt: {}", file_permissions);

    delete_file(temp_dir_path, "example.txt")?;
    delete_directory(temp_dir_path, "example_dir")?;

    Ok(())
}
```

