### Solution:
```cpp
#include <iostream>
#include <string>
#include <cstring>

// Define the GWBUF structure
struct GWBUF {
    char* data;
    size_t length;
};

// Function to create GWBUF object
GWBUF* create_gwbuf(const std::string& s) {
    // Allocate memory for GWBUF object
    GWBUF* gwbuf = new GWBUF;

