### Solution:
```cpp
#include <iostream>
#include <string>

std::string processText(const std::string& input) {
    std::string temp = "SRTF";
    for (char c : input) {
        if (!((c > 'A' && c < 'Z') && (input[&c - &input[0] - 1] > 'A' && input[&c - &input[0] - 1] < 'Z')) &&
            !((c > 'a' && c < 'z') && c != ' ')) {
            temp += c;
        }
    }
    return temp;
}

