use std::collections::HashMap;
use statrs::statistics::Statistics;

fn calculate_summary(dataset: &[f64]) -> HashMap<String, f64> {
    let mut summary: HashMap<String, f64> = HashMap::new();

    let count = dataset.len() as f64;
    let mean = dataset.iter().sum::<f64>() / count;
    let std = dataset.population_standard_deviation();
    let min = *dataset.iter().min().unwrap();

    summary.insert("count".to_string(), count);
    summary.insert("mean".to_string(), mean);
    summary.insert("std".to_string(), std);
    summary.insert("min".to_string(), min);

    let percentiles = vec![0.25, 0.5, 0.75];
    for &percentile in &percentiles {
        let percentile_value = dataset.percentile(percentile);
        summary.insert(format!("percentile_{}", (percentile * 100.0) as u32), percentile_value);
    }

    summary
}

fn main() {
    let dataset = vec![10.0, 20.0, 30.0, 40.0, 50.0];
    let summary = calculate_summary(&dataset);
    for (key, value) in summary {
        println!("{}: {}", key, value);
    }
}
