/// A `TabBarPosition` for defining the position of a `TabBar`.
#[derive(Clone, Hash)]
pub enum TabBarPosition {
    Top,
    Bottom,
    Left,
    Right,
}

impl TabBarPosition {
    /// Get the string representation of the position.
    pub fn as_str(&self) -> &str {
        match self {
            TabBarPosition::Top => "Top",
            TabBarPosition::Bottom => "Bottom",
            TabBarPosition::Left => "Left",
            TabBarPosition::Right => "Right",
        }
    }

