        *self = match *self {
            TabBarPosition::Top => TabBarPosition::Right,
            TabBarPosition::Right => TabBarPosition::Bottom,
            TabBarPosition::Bottom => TabBarPosition::Left,
            TabBarPosition::Left => TabBarPosition::Top,
        };
