        *self = match *self {
            TabBarPosition::Top => TabBarPosition::Left,
            TabBarPosition::Left => TabBarPosition::Bottom,
            TabBarPosition::Bottom => TabBarPosition::Right,
            TabBarPosition::Right => TabBarPosition::Top,
        };
    }
}
