```

### Solution:
```cpp
#include <vector>
#include <string>
#include <sstream>
#include "base.h"  // Assume base::IntToString is a function to convert int to string

std::vector<std::string> generateConfigurations(const std::vector<std::string>& ips, const std::vector<std::string>& hostnames, const std::vector<int>& ports) {
    std::vector<std::string> configurations;

    for (const auto& ip : ips) {
        for (const auto& hostname : hostnames) {
            for (const auto& port : ports) {
                std::stringstream configStream;
                configStream << "passport:" << ip << ":" << hostname << ":" << base::IntToString(port) << ":";
                configurations.push_back(configStream.str());
            }
        }
    }

    return configurations;
}
```

The `generateConfigurations` function takes in vectors of IPs, hostnames, and ports and iterates through each combination to construct the unique configuration strings. It uses a stringstream to build each configuration string and then adds it to the result vector. Finally, it returns the vector containing all the unique configuration strings.

