- `convertToDecimal("0xFF", 16)` should return 255
- `convertToDecimal("-0b1101.101", 2)` should return -13.625

### Solution:
```javascript
function convertToDecimal(s, fromBase) {
    let prefixRE = "";
    if (fromBase == 16) {
        prefixRE = "0x";
    } else if (fromBase == 8) {
        prefixRE = "0c";
    } else if (fromBase == 2) {
        prefixRE = "0b";
    }

    let parts = new RegExp("^([+\\-]?)(" + prefixRE + ")?([0-9a-z]*)(?:\\.\\d*)?$", "i").exec(s);
    if (parts != null) {
        let sign = parts[1] === "-" ? -1 : 1;
        let numberPart = parts[3];
        let decimalValue = parseInt(numberPart, fromBase);
        if (parts[0].includes(".")) {
            let fractionalPart = parts[0].split(".")[1];
            let fractionalValue = parseInt(fractionalPart, fromBase) / Math.pow(fromBase, fractionalPart.length);
            return sign * (decimalValue + fractionalValue);
        } else {
            return sign * decimalValue;
        }
    }
    return NaN; // Invalid input
}

// Test cases
console.log(convertToDecimal("1010", 2)); // Output: 10
console.log(convertToDecimal("0xFF", 16)); // Output: 255
console.log(convertToDecimal("-0b1101.101", 2)); // Output: -13.625
```

The `convertToDecimal` function first determines the prefix based on the input base and then uses a regular expression to extract the sign, prefix, and number part from the input string. It then converts the number part to decimal using the specified base and handles the fractional part if present, finally returning the decimal equivalent.

