### Solution:
```rust
fn count_unique_modules(code: &str) -> usize {
    let mut unique_modules = std::collections::HashSet::new();
    for line in code.lines() {
        if let Some(module_path) = line.strip_prefix("use ") {
            let module_path = module_path.trim_end_matches(';').trim();
            if let Some(module_name) = module_path.split("::").next() {
