### Solution:
```rust
// Struct representing a GUI font
struct Font {
    name: String,
    height: i32,
}

impl Font {
    // Create a Font instance from a GUI font string
    // Format: "font:name:h<height>", where "name" is the font name and "height" is the font height
    // If height is not specified, it defaults to DEFAULT_HEIGHT
    fn from_guifont(font_string: &str) -> Result<Font, String> {
        let parts: Vec<&str> = font_string.split(':').collect();
        if parts.len() != 2 {
            return Err("Invalid font string format".to_string());
        }

        let font_info: Vec<&str> = parts[1].split(':').collect();
        if font_info.len() != 2 {
            return Err("Invalid font string format".to_string());
        }

        let name = font_info[0].to_string();
        let height_str = font_info[1].trim_start_matches("h");
        let height = if height_str.is_empty() {
            DEFAULT_HEIGHT
        } else {
            match height_str.parse::<i32>() {
                Ok(h) => h,
                Err(_) => return Err("Invalid font height".to_string()),
            }
        };

        Ok(Font { name, height })
    }
}

// Default height for fonts
const DEFAULT_HEIGHT: i32 = 12;
```

