        'ENGINE': 'django.db.backends.sqlite3',
        'NAME': 'mydatabase'
    }
}
```

### Solution:
```python
def generate_django_settings(settings_dict):
    def format_value(value, indent_level=1):
        if isinstance(value, dict):
            lines = []
            for k, v in value.items():
                lines.append(f"{'    ' * indent_level}{k} = {format_value(v, indent_level + 1)}")
            return '{\n' + ',\n'.join(lines) + '\n' + '    ' * (indent_level - 1) + '}'
        elif isinstance(value, list):
            return str(value)
        elif isinstance(value, str):
            return f"'{value}'"
        else:
            return str(value)

    lines = []
    for key, value in settings_dict.items():
        lines.append(f"{key} = {format_value(value)}")

    return '\n'.join(lines)
```

