enum YAxisOptions {
    TIMES_LOWER_REF_VALUE,
    TIMES_UPPER_REF_VALUE
}

function processLabel(label: string, yAxisOption: YAxisOptions): string {
    switch (yAxisOption) {
        case YAxisOptions.TIMES_LOWER_REF_VALUE:
            const lowerRefPattern = /pattern/; // Replace 'pattern' with the specific pattern to match
