use smallvec::SmallVec;
use std::str::FromStr;

lazy_static! {
    static ref PATTERN: Regex = Regex::new(r"(\d+)").unwrap();
}

fn process_strings(input: &[&str]) {
    let mut numeric_values: SmallVec<[i32; 4]> = SmallVec::new();

    for &s in input {
        if let Some(captures) = PATTERN.captures(s) {
            if let Some(num_str) = captures.get(1) {
                if let Ok(num) = i32::from_str(num_str.as_str()) {
