    let product: i32 = numeric_values.iter().product();

    println!("Sum of numeric values: {}", sum);
    println!("Product of numeric values: {}", product);
}

fn main() {
    let input_strings = &["abc123def", "456xyz789", "pqr321stu"];
    process_strings(input_strings);
}
