const momentValue = /* moment object */;
const nullValue = null;
const numberValue = 42;

checkGuards(directoryPath, momentValue).then((result) => {
  console.log(result); // Output: ['isMoment']
});

checkGuards(directoryPath, nullValue).then((result) => {
  console.log(result); // Output: ['isNull']
});

checkGuards(directoryPath, numberValue).then((result) => {
  console.log(result); // Output: ['isNumber']
});
```

