    let name: String
    let dependencies: [String]
}
```

The `name` property represents the name of the test target, and the `dependencies` property is an array of strings representing the names of the test targets that the current test target depends on.

Your task is to implement a function `organizeTestTargets` that takes an array of `TestTarget` instances and returns a hierarchical representation of the test targets and their dependencies. The hierarchical representation should be in the form of a dictionary where the keys are the test target names, and the values are arrays of the dependent test target names.

Function Signature:
```swift
func organizeTestTargets(_ testTargets: [TestTarget]) -> [String: [String]]
```

For example, given the following input:
```swift
let testTargets = [
    TestTarget(name: "A", dependencies: ["B", "C"]),
    TestTarget(name: "B", dependencies: ["D"]),
    TestTarget(name: "C", dependencies: []),
    TestTarget(name: "D", dependencies: []),
    TestTarget(name: "E", dependencies: ["A", "F"]),
    TestTarget(name: "F", dependencies: ["D"]),
]
```

The function `organizeTestTargets` should return the following hierarchical representation:
```swift
[
    "A": ["B", "C", "D"],
    "B": ["D"],
    "C": [],
    "D": [],
    "E": ["A", "F", "B", "C", "D"],
    "F": ["D"]
]
```

### Solution:
```swift
func organizeTestTargets(_ testTargets: [TestTarget]) -> [String: [String]] {
    var dependencyMap: [String: [String]] = [:]

    // Create a map of test targets and their dependencies
    for target in testTargets {
        dependencyMap[target.name] = target.dependencies
    }

    // Function to recursively resolve dependencies
    func resolveDependencies(for target: String) -> [String] {
        var resolvedDependencies: [String] = []

        if let dependencies = dependencyMap[target] {
            for dependency in dependencies {
                resolvedDependencies.append(contentsOf: resolveDependencies(for: dependency))
            }
        }

        return Array(Set(resolvedDependencies + dependencyMap[target, default: []]))
    }

    // Create the hierarchical representation
    var organizedTestTargets: [String: [String]] = [:]
    for target in testTargets {
        organizedTestTargets[target.name] = resolveDependencies(for: target.name)
    }

    return organizedTestTargets
}

