- The button text may contain any alphanumeric characters, spaces, or special characters.

### Solution:
```javascript
function extractButtonText(htmlCode) {
    const buttonRegex = /<button[^>]*>(.*?)<\/button>/;
    const match = htmlCode.match(buttonRegex);
    if (match) {
        const buttonContent = match[1];
        // Remove any HTML tags within the button content
        const buttonText = buttonContent.replace(/<[^>]*>/g, '');
        return buttonText.trim();
    } else {
        return "Button not found";
    }
}

