### Solution:
```javascript
function validateJSONWithSchema(json, schema) {
  const resolveReference = (ref, obj) => {
    const tokens = ref.split('/').slice(1);
    let current = obj;
    for (const token of tokens) {
      current = current[token];
    }
    return current;
  };

  const validate = (data, schema) => {
    if (schema.$ref) {
      const resolvedSchema = resolveReference(schema.$ref, schema);
      return validate(data, resolvedSchema);
    }

    if (schema.type === 'object') {
      for (const key in schema.properties) {
        if (!validate(data[key], schema.properties[key])) {
          return false;
        }
      }
      return true;
    } else if (schema.type === 'array') {
      if (!Array.isArray(data)) {
        return false;
      }
      for (let i = 0; i < data.length; i++) {
        if (!validate(data[i], schema.items)) {
          return false;
        }
      }
      return true;
    } else {
      // Perform type-specific validation here
      if (schema.type === 'string' && typeof data !== 'string') {
        return false;
      }
      if (schema.type === 'number' && typeof data !== 'number') {
        return false;
      }
      // Add more type validations as needed

      // Perform additional validations (e.g., required properties, enum values, etc.)
      if (schema.required && !schema.required.every(prop => data.hasOwnProperty(prop))) {
        return false;
      }
      if (schema.enum && !schema.enum.includes(data)) {
        return false;
      }

      return true;
    }
  };

  return validate(json, schema);
}
```

This solution provides a function `validateJSONWithSchema` that resolves JSON references and validates a given JSON object against a JSON schema. It uses recursive validation to handle nested objects and arrays, and performs type-specific and additional validations as specified in the schema. The function returns `true` if the JSON object is valid according to the schema, and `false` otherwise.

