### Solution:
```rust
use std::fs;
use std::path::Path;

fn list_files_in_directory(directory_path: &str) -> Vec<String> {
    let mut files_list = Vec::new();
    if let Ok(entries) = fs::read_dir(directory_path) {
        for entry in entries {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_file() {
                    if let Some(file_path) = path.to_str() {
                        files_list.push(file_path.to_string());
                    }
                } else if path.is_dir() {
                    let sub_directory_path = path.to_str().unwrap();
                    let sub_directory_files = list_files_in_directory(sub_directory_path);
                    files_list.extend(sub_directory_files);
                }
            }
        }
    }
    files_list
}
```

