function convertPaddingShorthand(padding) {
  const values = padding.split(' ').map(val => {
    if (val.includes('px')) {
      return parseInt(val);
    } else {
      return 0;
    }
  });

  switch (values.length) {
    case 1:
      return [values[0], values[0], values[0], values[0]];
    case 2:
      return [values[0], values[1], values[0], values[1]];
    case 3:
      return [values[0], values[1], values[2], values[1]];
    case 4:
      return values;
    default:
      return [0, 0, 0, 0];
  }
}

