    println!("{:#?}", dsn);
    assert_eq!(dsn.driver, "mysql");
    assert_eq!(dsn.username.unwrap(), "root");
    assert_eq!(dsn.password.unwrap(), r#"!A4T@hh'c<PASSWORD>""#);
