    // your implementation
}
```

Example:
```rust
fn main() {
    let url = "mysql://root:%21%41%34%54%40%68%68%27%63%55%6a%37%4c%58%58%76%6b%22@tcp(10.0.0.1:3306)/test";
    let decoded_password = decode_password(url);
    println!("{}", decoded_password); // Output: !A4T@hh'cUj7LXXvk"
}
```

### Solution:
```rust
fn decode_password(url: &str) -> String {
    let parts: Vec<&str> = url.split(':').collect();
    if parts.len() < 3 {
        panic!("Invalid URL format");
    }
    let encoded_password = parts[2].split('@').next().unwrap();
    let decoded_password = hex_decode(encoded_password);
    decoded_password
}

fn hex_decode(encoded: &str) -> String {
    let mut decoded = String::new();
    let mut bytes = Vec::new();
    let mut i = 0;
    while i < encoded.len() {
        if &encoded[i..i + 1] == "%" {
            let byte = u8::from_str_radix(&encoded[i + 1..i + 3], 16).unwrap();
            bytes.push(byte);
            i += 3;
        } else {
            bytes.push(encoded.as_bytes()[i]);
            i += 1;
        }
    }
    decoded.push_str(&String::from_utf8(bytes).unwrap());
    decoded
}
```

The `decode_password` function first splits the URL to extract the encoded password. It then uses the `hex_decode` function to decode the password from its hexadecimal representation. The `hex_decode` function iterates through the encoded string, decoding each pair of hexadecimal characters and appending the corresponding ASCII character to the decoded password string.

