use criterion::{criterion_group, criterion_main, Criterion};

fn calculate_average_time(functions: Vec<fn()>) -> String {
    let mut result = String::new();
    let mut group = criterion_group::criterion_group("benchmark_group");

    for (index, function) in functions.iter().enumerate() {
        group.bench_function(format!("Function {}", index), |b| b.iter(|| function()));
    }

