### Solution:
```rust
use std::io::{self, Write};
use std::sync::{Mutex, Arc};

lazy_static::lazy_static! {
    static ref BUFFER: Mutex<Vec<u8>> = Mutex::new(Vec::new());
    pub static ref LINE_STDOUT: Arc<Mutex<io::LineWriter<io::Stdout>>> = {
        let stdout = io::stdout();
        Arc::new(Mutex::new(io::LineWriter::new(stdout)))
    };
}

pub fn write_to_buffer(s: &str) {
    let mut buffer = BUFFER.lock().unwrap();
    buffer.write_all(s.as_bytes()).unwrap();
}

pub fn flush_buffer_to_stdout() {
    let mut buffer = BUFFER.lock().unwrap();
    let mut stdout = LINE_STDOUT.lock().unwrap();
    stdout.write_all(&buffer).unwrap();
    stdout.flush().unwrap();
    buffer.clear();
}

pub fn clear_written_content() {
    let mut buffer = BUFFER.lock().unwrap();
    buffer.clear();
}

pub fn get_buffered_content() -> Vec<u8> {
    BUFFER.lock().unwrap().clone()
}

pub fn get_written_content() -> Vec<u8> {
    let buffer = BUFFER.lock().unwrap();
    let mut stdout = LINE_STDOUT.lock().unwrap();
    stdout.flush().unwrap();
    let written_content = stdout.get_ref().clone();
    written_content
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_buffered_output() {
        write_to_buffer("Hello, ");
        write_to_buffer("World!");
        let buffered = get_buffered_content();
        assert_eq!(buffered, b"Hello, World!");

        flush_buffer_to_stdout();
        let written = get_written_content();
        assert_eq!(written, b"Hello, World!\n");
    }
}
```

In the solution, a `BUFFER` is defined as a `Mutex<Vec<u8>>` to store the buffered content. The `LINE_STDOUT` is defined as a global variable to access the standard output. Functions are implemented to write to the buffer, flush the buffer to the standard output, clear the written content, and retrieve the buffered and written content. The provided test case in the `submodule` module is also implemented to ensure the correctness of the buffered output system.

