### Solution:
```swift
import Foundation
import SwiftUI

struct CircleText: View {
    let radius: CGFloat
    let text: String

    var body: some View {
        GeometryReader { geometry in
            ZStack {
                ForEach(0..<text.count, id: \.self) { index in
                    let angle = -Double(index) * 2 * .pi / Double(text.count)
                    let x = radius * CGFloat(cos(angle)) + geometry.size.width / 2
                    let y = radius * CGFloat(sin(angle)) + geometry.size.height / 2
                    Text(String(text[text.index(text.startIndex, offsetBy: index)]))
                        .position(x: x, y: y)
                }
            }
        }
    }
}

