fn generate_error_handling_code(error_definitions: &[(String, Vec<String>)]) -> String {
    let mut code = String::new();

    code.push_str("fn handle_error(error: &Error) {\n");
    code.push_str("    match error {\n");

    for (error_type, fields) in error_definitions {
        code.push_str(&format!("        {} {{ ", error_type));
        for field in fields {
            code.push_str(&format!("{}, ", field));
        }
        code.push_str("} => {\n");
        code.push_str(&format!("            println!(\"{}: {{}}\", {});\n", error_type, fields.iter().map(|f| format!("{}:? ", f)).collect::<String>()));
        code.push_str("        }\n");
    }

    code.push_str("    }\n");
    code.push_str("}\n");

    code
}
```

