### Solution:
```rust
use std::fs;
use std::path::Path;

pub fn select_files(directory_path: &str, extension: &str) -> Result<Vec<String>, String> {
    let dir = Path::new(directory_path);
    if !dir.is_dir() {
        return Err("Invalid directory path".to_string());
    }

    let files = match fs::read_dir(dir) {
        Ok(files) => files,
        Err(_) => return Err("Error reading directory".to_string()),
    };

    let mut selected_files = Vec::new();
    for file in files {
        if let Ok(file) = file {
            if let Some(file_name) = file.file_name().to_str() {
                if file_name.ends_with(extension) {
                    selected_files.push(file_name.to_string());
                }
            }
        }
    }

    if selected_files.is_empty() {
        return Err("No files with the specified extension found".to_string());
    }

    Ok(selected_files)
}
```

This solution provides a `select_files` function that takes a directory path and a file extension as input and returns a vector of file names with the specified extension. It handles potential errors such as invalid directory path, error reading directory, and no files found with the specified extension. The function uses the `std::fs` module to read the directory contents and filter the files based on the given extension.

