### Solution:
```rust
use sha2::{Sha256, Digest};
use std::fmt;

struct Signature(String);

impl Signature {
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

fn calculate_sha256_hash(input: &str) -> String {
    let mut hasher = Sha256::new();
    hasher.update(input);
    let hashed = hasher.finalize();
    let mut hexa = String::with_capacity(hashed.len()*2);
    for b in hashed {
        write!(&mut hexa, "{:02X}", b).expect("Error writing to hexa");
    }
    hexa
}

fn main() {
    let input_string = "Hello, World!";
    let hash = calculate_sha256_hash(input_string);
    let signature = Signature(hash);
    println!("SHA-256 Hash: {}", signature.as_str());
}
```

