use std::collections::HashMap;
use std::fs;
use std::path::Path;

fn read_entries(dir: &mut fs::ReadDir) -> Result<HashMap<String, fs::Metadata>, std::io::Error> {
    let mut entries_map = HashMap::new();

    for entry in dir {
        let entry = entry?;
        let path = entry.path();
        let file_name = path.file_name().and_then(|s| s.to_str()).map(String::from);

        if let Some(file_name) = file_name {
            if let Ok(metadata) = fs::metadata(&path) {
                entries_map.insert(file_name, metadata);
            }
        }
    }

    Ok(entries_map)
}

