function findMissingFiles(localVideoFile, remoteVideoPart) {
    const remoteFilenames = remoteVideoPart.map(part => part.filename);
    const missingFiles = localVideoFile.filter(file => !remoteFilenames.includes(file.localFilePath.split('/').pop()));
