```rust
use std::collections::HashSet;

struct Transaction;
struct MembershipSystem {
    addr: String,
}

impl MembershipSystem {
    fn send_query(&self, tx: Transaction, peer_addr: String) {
        // Implementation not shown
    }

    fn simulate_membership_system(K: usize, self_addr: String, membership: HashSet<String>) {
        let mut members = membership.clone().into_iter().collect::<Vec<String>>();
        members.push(self_addr.clone()); // Add self_addr to the list of members
        let mut rng = rand::thread_rng();
        members.shuffle(&mut rng); // Shuffle the list of members

        for peer_addr in members.iter().take(K) {
            self.send_query(Transaction, peer_addr.clone());
        }
    }
}
```

