    #endif /* SFMT_PARAMS607_H */
    )";

    std::pair<std::string, std::string> result = parseHeaderFile(headerContent);
    std::cout << "Macro Definition: " << result.first << std::endl;
    std::cout << "Unique Identifier: " << result.second << std::endl;

    return 0;
}
```

