    if isinstance(obj, dict):
        return _pretty_dict(obj)
    elif isinstance(obj, list):
        return _pretty_list(obj)
    elif isinstance(obj, tuple):
        return _pretty_tuple(obj)
    elif isinstance(obj, str):
        return _pretty_string(obj)
    else:
