        return "[" + ", ".join([_pretty(item) for item in lst]) + "]"
    else:
        return "[" + ", ".join([_pretty(item) for item in lst]) + "]"

def _pretty_tuple(tpl):
    if pprint_use_unicode:
        return "(" + ", ".join([_pretty(item) for item in tpl]) + ")"
    else:
