pub struct StacklessBytecodeGenerator;

impl StacklessBytecodeGenerator {
    pub fn generate_bytecode(program: &str) -> Vec<(u8, String)> {
        let mut bytecode = Vec::new();
        let operations = program.split(';'); // Assuming operations are separated by ';'

        for operation in operations {
            let tokens: Vec<&str> = operation.trim().split(' ').collect();
            match tokens[0] {
                "add" => bytecode.push((0, String::new())),
                "sub" => bytecode.push((1, String::new())),
