fn process_instruction(outputter: &mut Outputter, instruction: u32) -> Option<String> {
    let opcode = instruction >> 26; // Extract the opcode from the instruction

    match opcode {
        0b1100011 => {
            let rs1 = (instruction >> 15) & 0b11111;
            let rs2 = (instruction >> 20) & 0b11111;
            let imm = ((instruction >> 31) << 12) | ((instruction >> 25) & 0b111111) | ((instruction >> 7) & 0b1111111) | ((instruction >> 20) & 0b1);
            let offset = outputter.insn_pc.wrapping_add(imm);
