use syn::parse_quote;
use syn::ItemFn;

fn process_code_snippet(code: &str) -> (bool, usize, usize) {
    let parsed_fn: syn::ItemFn = syn::parse_str(code).unwrap();
    let mut pattern_count = 0;
    let mut identifiers = std::collections::HashSet::new();

    // Iterate through the function body to find the specific pattern
    parsed_fn
        .block
        .stmts
        .iter()
        .for_each(|stmt| {
            if let syn::Stmt::Expr(expr) = stmt {
                if let syn::Expr::Match(expr_match) = &**expr {
                    for arm in &expr_match.arms {
                        if let syn::Pat::TupleStruct(tuple_struct) = &*arm.pat {
