use serde_json::{Value, json};

fn sort_fruits(json_str: &str) -> String {
    let mut json_value: Value = serde_json::from_str(json_str).unwrap();
    if let Some(fruits) = json_value.get_mut("fruits") {
        if let Value::Array(ref mut arr) = *fruits {
