public void InsertNetworks(List<string> networkData, MySqlConnection dbConnection)
{
    int i = 1; // Initialize the unique ID counter

    foreach (var network in networkData)
    {
        string query = "INSERT INTO networks(id, network) VALUES (@id, @network)";

