}
```

### Solution:
```rust
fn process_parameters(params: Vec<Parameter>) -> Vec<ModifiedParameter> {
    let modified_params: Vec<ModifiedParameter> = params
        .into_iter()
        .filter_map(|param| {
            match param.value {
                Value::Int(_) | Value::Str(_) | Value::Bool(_) => Some(param),
                _ => None,
            }
        })
        .map(|param| {
            match param.value {
