```

### Solution:
```javascript
function resolveModuleImports(indexContent) {
  const importRegex = /from\s+['"]([^'"]+)['"]/g;
  const matches = indexContent.match(importRegex);
  if (matches) {
    return matches.map(match => match.split(/['"]/)[1]);
  } else {
    return [];
  }
}

