### Solution:
```typescript
function extractPropertyNames(interfaceString: string): string[] {
  const properties: string[] = [];
  let insideInterface = false;
  let currentProperty = '';

  for (let i = 0; i < interfaceString.length; i++) {
    if (interfaceString[i] === '{') {
      insideInterface = true;
    } else if (interfaceString[i] === '}') {
      insideInterface = false;
    } else if (insideInterface && interfaceString[i] === ';') {
      const propertyName = currentProperty.trim().split(':')[0];
      properties.push(propertyName);
      currentProperty = '';
    } else if (insideInterface) {
      currentProperty += interfaceString[i];
    }
  }

  return properties;
}

