use std::collections::HashSet;

pub fn process_auto_types(auto_types: &[AutoType]) -> (usize, String, Vec<AutoTypeAssociation>) {
    let enabled_count = auto_types.iter().filter(|at| at.enabled).count();

    let sequence_string = auto_types
        .iter()
        .filter_map(|at| at.sequence.as_ref())
        .filter(|&seq| !seq.is_empty())
        .map(|seq| seq.to_string())
        .collect::<Vec<String>>()
        .join(",");

