### Solution:
```rust
fn process_spans(spans: &[(usize, usize)]) -> (String, Option<ParseError>) {
    if spans.is_empty() {
        return (String::new(), None);
    }

    if let Ok(s) = std::str::from_utf8(&spans[0]) {
        let mut result = String::from(s);
        for &(start, end) in &spans[1..] {
            if let Ok(s) = std::str::from_utf8(&spans[start..end]) {
