export * from './inline-void';
export * from './node-id';
export * from './withToggleType';
```

The `<gh_stars>` tag indicates the number of GitHub stars for the subsequent exported module. Each `export * from` line represents an exported module from a file. Your task is to parse the TypeScript file, extract the module names, and calculate the total number of GitHub stars for each module.

Write a program that takes the TypeScript file as input and outputs the total number of GitHub stars for each module in the following format:

```
Module: inline-void, Total GitHub Stars: <stars>
Module: node-id, Total GitHub Stars: <stars>
Module: withToggleType, Total GitHub Stars: <stars>
```

Assume that the TypeScript file will always follow the given format, and the module names will not contain any special characters or spaces.

### Solution:
```typescript
const fs = require('fs');

function calculateGitHubStars(fileContent) {
  const lines = fileContent.split('\n');
  const moduleStarsMap = new Map();

  let currentStars = 0;
  let currentModule = '';

  for (const line of lines) {
    if (line.startsWith('<gh_stars>')) {
      currentStars = parseInt(line.substring(10));
    } else if (line.startsWith('export * from')) {
      currentModule = line.split('./')[1].replace("';", '');
      if (moduleStarsMap.has(currentModule)) {
        moduleStarsMap.set(currentModule, moduleStarsMap.get(currentModule) + currentStars);
      } else {
        moduleStarsMap.set(currentModule, currentStars);
      }
    }
  }

  for (const [module, stars] of moduleStarsMap) {
    console.log(`Module: ${module}, Total GitHub Stars: ${stars}`);
  }
}

