function parseCSS(cssString) {
    const rules = cssString.split('\n').filter(rule => rule.trim() !== ''); // Split the string into individual rules
    const parsedCSS = {}; // Object to store parsed CSS rules

    rules.forEach(rule => {
        const [selector, properties] = rule.split('{').map(part => part.trim()); // Split the rule into selector and properties
        const cleanedSelector = selector.replace(/\s/g, ''); // Remove any whitespace from the selector

        const parsedProperties = properties.split(';').reduce((acc, property) => {
            const [key, value] = property.split(':').map(part => part.trim()); // Split the property into key and value
            if (key && value) {
                acc[key] = value; // Add the property to the parsed properties object
            }
            return acc;
        }, {});

        parsedCSS[cleanedSelector] = parsedProperties; // Add the parsed selector and properties to the parsed CSS object
    });

    return parsedCSS;
}

