/**
 * Creates a date formatting utility based on the provided options.
 * @param options - An object containing formatting options.
 * @returns A function that formats the input date string according to the specified output format.
 */
export const createDateFormatter = ({
  formatFrom = ['yyyy-MM-dd', 'dd.MM.yyyy'],
  formatTo = 'dd MMMM yyyy',
  invalidPlaceholder = '',
}: {
  formatFrom?: string | string[];
  formatTo?: string | ((d: Date) => string);
  invalidPlaceholder?: any;
