### Solution:
```rust
use sha1::{Digest, Sha1};

enum ObjectType {
    Commit,
    Tree,
    Blob,
    Tag,
    OfsDelta(u32),
}

fn git_sha1(object_type: &str, content_length: usize, content: &str) -> String {
    let mut input = String::new();
    input.push_str(object_type);
    input.push(' ');
    input.push_str(&content_length.to_string());
    input.push('\0');
    input.push_str(content);

    let mut hasher = Sha1::new();
    hasher.update(input);
    let result = hasher.finalize();

    format!("{:x}", result)
}

fn calculate_git_object_hash(object_type: ObjectType, content: &str) -> String {
    match object_type {
        ObjectType::Commit => git_sha1("commit", content.len(), content),
        ObjectType::Tree => git_sha1("tree", content.len(), content),
        ObjectType::Blob => git_sha1("blob", content.len(), content),
        ObjectType::Tag => git_sha1("tag", content.len(), content),
        ObjectType::OfsDelta(offset) => {
            // Handle offset delta type
            let offset_str = format!("o{}", offset);
            git_sha1(&offset_str, content.len(), content)
        }
    }
}

fn main() {
    let object_type = ObjectType::Blob;
    let content = "Sample blob content";
    let hash = calculate_git_object_hash(object_type, content);
    println!("Hash of the Git object: {}", hash);
}
```

