def convert_to_numeric(phone_number):
    numeric_phone = ''
    for ch in phone_number:
        if ch.islower():
            ch = ch.upper()
        if ch.isdigit():
            numeric_phone += ch
        elif ch == '-':
            numeric_phone += '-'
        elif ch in ['A', 'B', 'C']:
