    let message1 = "\u{1b}[34mRECEIVE   \u{1b}[38;5;216m100\u{1b}[38;5;208m'abc'";
    let message2 = "\u{1b}[34mRECEIVE   \u{1b}[38;5;216m50\u{1b}[38;5;208m'def'";
