use regex::Regex;

fn process_message(message: &str) -> Option<(u32, String)> {
    let re = Regex::new(r"\u{1b}\[34mRECEIVE   \u{1b}\[38;5;216m(\d+)\u{1b}\[38;5;208m'(.+)'").unwrap();
    if let Some(captures) = re.captures(message) {
        let amount = captures.get(1).unwrap().as_str().parse::<u32>().unwrap();
