**Input:**
- The input `fileContent` is a string representing the content of a TypeScript file. The file content may contain multiple lines of code, and the `imports` array may appear at any position within the file.

**Output:**
- The function should return an array of imported module names extracted from the `imports` array in the file content.

**Example:**
```typescript
const fileContent = `
    imports: [
        CommonModule,
        RouterModule,
        HttpModule,
        FormsModule,
        ReactiveFormsModule,
        productRouting
    ],
    // Other code may exist here
`;

const importedModules = extractImportedModules(fileContent);
console.log(importedModules);
// Output: ["CommonModule", "RouterModule", "HttpModule", "FormsModule", "ReactiveFormsModule", "productRouting"]
```

### Solution:
```typescript
function extractImportedModules(fileContent: string): string[] {
    const importsStartIndex = fileContent.indexOf('imports: [');
    if (importsStartIndex === -1) {
        return [];
    }

    const importsEndIndex = fileContent.indexOf(']', importsStartIndex);
    if (importsEndIndex === -1) {
        return [];
    }

    const importsContent = fileContent.substring(importsStartIndex, importsEndIndex + 1);
    const moduleNames = importsContent
        .replace('imports: [', '') // Remove the 'imports: [' part
        .replace(/\s/g, '') // Remove all whitespaces
        .replace(/,/g, '') // Remove all commas
        .split('\n') // Split by new line
        .filter(module => module.trim() !== ''); // Remove empty lines

    return moduleNames;
}
```

