### Solution:
```javascript
// gitSnapshot.js
const git = require('simple-git/promise');
const snapshot = require('git-snapshot');
const path = require('path');
const fs = require('fs-extra');

/**
 * Clones a Git repository, checks out the specified branch, and saves a snapshot at the destination directory.
 * @param {string} repoUrl - The URL of the Git repository.
 * @param {string} branchName - The name of the branch to checkout.
 * @param {string} destDir - The destination directory to save the snapshot.
 * @returns {Promise<string>} - A promise that resolves with the path to the saved snapshot directory.
 */
async function createGitSnapshot(repoUrl, branchName, destDir) {
  const tempDir = path.join(destDir, 'temp');
  const snapshotDir = path.join(destDir, 'snapshot');

  // Clone the repository to a temporary directory
  await snapshot.clone(repoUrl, tempDir);

  // Checkout the specified branch
  const repo = git(tempDir);
  await repo.checkout(branchName);

  // Copy the repository to the snapshot directory
  await fs.copy(tempDir, snapshotDir);

  // Clean up the temporary directory
  await fs.remove(tempDir);

  return snapshotDir;
}

module.exports = createGitSnapshot;
```

In this solution, the `createGitSnapshot` function uses the "git-snapshot" module to clone the Git repository to a temporary directory. It then uses the "simple-git" module to checkout the specified branch. After that, it copies the repository to the destination directory and cleans up the temporary directory before resolving with the path to the saved snapshot directory.

