### Solution:
```rust
use std::ops::Deref;

/// This is a special type of buffer that can be used as destination for rendering.
pub struct WebGLFrameBuffer<T>(pub T);
impl<T> Deref for WebGLFrameBuffer<T> {
    type Target = T;
    fn deref(&self) -> &Self::Target {
        &self.0
    }
}

/// Utility function to print messages to stdout (native) or the js console (web)
pub fn print(s: &str) {
    GLContext::print(s);
}

/// Renders a message to the provided WebGLFrameBuffer and prints it to the console based on the environment
pub fn render_to_framebuffer(framebuffer: &WebGLFrameBuffer<String>, message: &str) {
    let mut content = framebuffer.0.to_string();
    content.push_str(message);
    framebuffer.0 = content;

    #[cfg(target_arch = "wasm32")]
    print(message);
    #[cfg(not(target_arch = "wasm32"))]
    println!("{}", message);
}
```

